  // Menús acumulados: las opciones anteriores permanecen visibles para poder cambiarlas.
  const steps=['Plomería',state.material,state.section,state.material==='Fontanería'?'':state.size,state.family,state.length].filter(Boolean);
  const base=`<div class="pl-head"><div><span class="pl-eyebrow">PLOMERÍA · NAVARRO 360</span><h3>Elige material, medida y presentación</h3><p>Todos los menús anteriores siguen visibles. Cambia cualquier selección sin empezar desde cero.</p></div><button class="pl-reset" type="button" data-pl-reset="1">↶ Limpiar selección</button></div>`;
