  const step=(num,title,buttons,ready)=>`<section class="pl-persist-step ${ready?'pl-step-ready':'pl-step-wait'}" aria-label="Paso ${num}: ${textSafe(title)}"><div class="pl-persist-heading"><span class="pl-step-number">${num}</span><h4 class="pl-step-title">${textSafe(title)}</h4>${ready?'<span class="pl-step-done">✓ Seleccionado</span>':''}</div>${buttons}</section>`;
