    const eligible=ROWS.filter(r=>dictionary.has(String(r[0]))&&r[1]===state.material&&(!galvanized||(state.section==='Niples rectos'?r[3]==='Niples rectos':state.section==='Tubos'?r[3]==='Tubos':r[3]!=='Niples rectos'&&r[3]!=='Tubos')));
